public TAMRebateLine TAMRebateLine(TAMRebateLine _relatedTable = null)
{
    if (prmIsDefault(_relatedTable))
    {
        return this.setLink(tableStr('TAMRebateLine'));
    }

    return this.setLink(tableStr('TAMRebateLine'), _relatedTable);
}

private boolean checkRecognizeAmount()
{
    boolean ok = true;

    if (this.RecognizeAmount == 0)
    {
        ok = checkFailed("@GlobalUnifiedPricing:GUPRebateAmortizationCannotHaveZeroRecognizeAmount");
    }
    else
    {
        TAMRebateDeductionAmount rebateAmount = GUPRebateAmortizationScheduleDetail::getTotalRebateAmount(this.TAMRebateLine);
        TAMRebateDeductionAmount accumulatedAmount = GUPRebateAmortizationScheduleDetail::getTotalAccumulatedAmount(this.TAMRebateLine, this.PeriodNumber);

        if (this.RecognizeAmount > rebateAmount - accumulatedAmount)
        {
            ok = checkFailed(strFmt("@GlobalUnifiedPricing:GUPRebateAmortizationCannotExceedMaximumRemainingAmount", rebateAmount - accumulatedAmount));
        }
    }

    return ok;
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ok = super(_fieldIdToCheck);

    if (ok)
    {
        switch(_fieldIdToCheck)
        {
            case fieldnum(GUPRebateAmortizationScheduleDetail, RecognizeAmount):
                ok = this.checkRecognizeAmount();
                break;
        }
    }

    return ok;
}

public static void createAmortizationScheduleDetails(TAMRebateLine rebateLine)
{
    GUPRebateAmortizationScheduleDetail scheduleDetail;
    real totalAmount = rebateLine.RebateAmount;
    RecordInsertList scheduleDetailInserted = new RecordInsertList(tableNum(GUPRebateAmortizationScheduleDetail));

    if (rebateLine && rebateLine.Occurrences > 0)
    {
        ttsbegin;

        delete_from scheduleDetail
            where scheduleDetail.TAMRebateLine == rebateLine.RecId;

        int lineCount = rebateLine.Occurrences;
        real amount = totalAmount / lineCount;
        amount = Global::roundZeroDec(amount, 2);

        real accumlatedAmount = amount;
        for (int i = 1; i <= lineCount; i++)
        {
            scheduleDetail.clear();
            scheduleDetail.TAMRebateLine = rebateLine.RecId;
            scheduleDetail.RecognizeAmount = amount;
            scheduleDetail.PeriodNumber = i;
            if (i == lineCount)
            {
                amount = totalAmount - accumlatedAmount + amount;
                accumlatedAmount = totalAmount;
                scheduleDetail.RecognizeAmount = amount;
            }
            else
            {
                accumlatedAmount = accumlatedAmount + amount;
            }

            scheduleDetailInserted.add(scheduleDetail);
        }

        scheduleDetailInserted.insertDatabase();

        ttscommit;
    }
}

public static GUPRebateAmortizationRecognizeAmount getSpecificPeriodAmount(TAMRebateLine rebateLine, GUPRebateAmortizationPeriodNumber _periodNumber)
{
    GUPRebateAmortizationScheduleDetail scheduleDetail;

    select firstonly scheduleDetail
        where scheduleDetail.TAMRebateLine == rebateLine.RecId
           && scheduleDetail.PeriodNumber  == _periodNumber;

    return scheduleDetail.RecognizeAmount;
}

internal static boolean exist(GUPRefRecId _rebateLineRecId, GUPRebateAmortizationPeriodNumber _periodNumber)
{
    GUPRebateAmortizationScheduleDetail scheduleDetail;

    if (!_rebateLineRecId)
    {
        return false;
    }

    if (!_periodNumber)
    {
        select firstonly RecId from scheduleDetail
            where scheduleDetail.TAMRebateLine == _rebateLineRecId;

        return scheduleDetail.RecId != 0;
    }

    select firstonly RecId from scheduleDetail
        where scheduleDetail.TAMRebateLine == _rebateLineRecId &&
        scheduleDetail.PeriodNumber == _periodNumber;

    return scheduleDetail.RecId != 0;
}

internal static GUPRebateAmortizationScheduleDetail find(GUPRefRecId _rebateLineRecId,
                                   GUPRebateAmortizationPeriodNumber _periodNumber,
                                   boolean _update = false)
{
    GUPRebateAmortizationScheduleDetail scheduleDetail;

    if (_rebateLineRecId && _periodNumber)
    {
        if (_update)
        {
            scheduleDetail.selectForUpdate(_update);
        }
        select firstonly scheduleDetail
             where scheduleDetail.TAMRebateLine == _rebateLineRecId &&
                   scheduleDetail.PeriodNumber == _periodNumber;

        return scheduleDetail;
    }

    return  scheduleDetail;
}

internal static TAMRebateDeductionAmount getTotalAccumulatedAmount(GUPRefRecId _rebateLineRecId, GUPRebateAmortizationPeriodNumber _periodNumber)
{
    GUPRebateAmortizationScheduleDetail scheduleDetail;

    select sum(RecognizeAmount) from scheduleDetail
        where scheduleDetail.TAMRebateLine == _rebateLineRecId
            && scheduleDetail.PeriodNumber != _periodNumber;

    return scheduleDetail.RecognizeAmount;
}

internal static TAMRebateDeductionAmount getTotalRemainingAmount(GUPRefRecId _rebateLineRecId)
{
    GUPRebateAmortizationScheduleDetail scheduleDetail;

    select sum(RecognizeAmount) from scheduleDetail
        where scheduleDetail.TAMRebateLine == _rebateLineRecId;

    return GUPRebateAmortizationScheduleDetail::getTotalRebateAmount(_rebateLineRecId) - scheduleDetail.RecognizeAmount;
}

internal static TAMRebateDeductionAmount getTotalRebateAmount(GUPRefRecId _rebateLineRecId)
{
    TAMRebateLine rebateLine;

    select firstonly rebateLine
        where rebateLine.RecId == _rebateLineRecId;
    return rebateLine.RebateAmount;
}

public boolean validateWrite()
{
    boolean ret = super();

    TAMRebateDeductionAmount rebateAmount = GUPRebateAmortizationScheduleDetail::getTotalRebateAmount(this.TAMRebateLine);
    TAMRebateDeductionAmount accumulatedAmount = GUPRebateAmortizationScheduleDetail::getTotalAccumulatedAmount(this.TAMRebateLine, this.PeriodNumber);

    if (accumulatedAmount + this.RecognizeAmount > rebateAmount)
    {
        ret = warning(strFmt("@GlobalUnifiedPricing:GUPRebateAmortizationTotalAmountGreaterThanTotalRebateAmount", rebateAmount));
    }

    return ret;
}
